INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (508, 1, 'binlog 켜기', 'MariaDB 는 **기본값으로 binlog(바이너리 로그)가 꺼져** 있습니다. binlog 는 데이터를 바꾼 문장(INSERT·UPDATE·DELETE 등)을 순서대로 기록하는 파일이고, 시점 복구의 재료입니다.

서버 설정 파일을 만들어 binlog 를 켜고 서버를 다시 시작하세요. 설정 파일은 `/etc/mysql/mariadb.conf.d/` 안에 `[mysqld]` 구역으로 만들면 됩니다.

- `log_bin=/var/lib/mysql/mysql-bin` : binlog 파일 이름의 앞부분(`mysql-bin.000001` 처럼 번호가 붙음)
- `server_id=1` : 서버 번호 (복제를 안 써도 로그에 기록됩니다)

서버를 끌 때는 `mariadb-admin shutdown`, 다시 켤 때는 `nohup mysqld_safe >/dev/null 2>&1 &` 를 쓰고, 접속이 될 때까지 몇 초 기다리세요.', '설정 파일은 아무 이름이나 `.cnf` 로 끝나면 됩니다. 서버를 재시작해야 반영됩니다. 켜졌는지는 `SHOW VARIABLES LIKE ''log_bin'';` 로 봅니다.', 'printf ''[mysqld]\\nlog_bin=/var/lib/mysql/mysql-bin\\nserver_id=1\\n'' > /etc/mysql/mariadb.conf.d/99-binlog.cnf
mariadb-admin shutdown
sleep 2
nohup mysqld_safe >/dev/null 2>&1 &
for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done
mariadb -e "SHOW VARIABLES LIKE ''log_bin''"

# log_bin 설정은 서버를 재시작해야 적용된다. 켜면 mysql-bin.000001 같은 파일에 변경 내용이 쌓인다', '["sh", "-c", "mariadb-admin shutdown >/dev/null 2>&1; for i in $(seq 1 30); do mariadb-admin ping >/dev/null 2>&1 || break; sleep 0.5; done; rm -f /etc/mysql/mariadb.conf.d/99-binlog.cnf; nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(mariadb -N -e \\"SELECT @@log_bin\\")\\" = 1 ] ) && ( mariadb -N -e \\"SHOW BINARY LOGS\\" | grep -q mysql-bin )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "log_bin 이 ON 이다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N -e \\"SELECT @@log_bin\\")\\" = 1 ]"]}, {"label": "binlog 파일 목록이 보인다", "cmd": ["sh", "-c", "mariadb -N -e \\"SHOW BINARY LOGS\\" | grep -q mysql-bin"]}]', '[{"title": "MariaDB 바이너리 로그", "url": "https://mariadb.com/kb/en/binary-log/"}, {"title": "mariadb-binlog", "url": "https://mariadb.com/kb/en/mariadb-binlog/"}]'),
  (508, 2, 'binlog 파일 이름과 현재 위치 확인', 'binlog 는 **파일 이름 + 파일 안의 위치(숫자)** 로 어디까지 기록했는지 가리킵니다. 지금 서버가 **기록 중인 binlog 파일 이름**을 `/tmp/file.txt` 에, **현재 위치(Position)** 를 `/tmp/pos.txt` 에 저장하세요. (값만, 제목 줄 없이)

(백업 → 변경 → 실수 DELETE 가 이미 벌어진 상태입니다. 지금은 위치를 읽는 연습만 합니다.)', '`SHOW MASTER STATUS;` 를 `mariadb -N -e` 로 실행하면 파일 이름, 위치 순서로 나옵니다. `cut -f1`, `cut -f2` 로 나눠 저장하세요. 전체 목록은 `SHOW BINARY LOGS;` 입니다.', 'mariadb -N -e ''SHOW MASTER STATUS'' | cut -f1 > /tmp/file.txt
mariadb -N -e ''SHOW MASTER STATUS'' | cut -f2 > /tmp/pos.txt
cat /tmp/file.txt /tmp/pos.txt

# SHOW MASTER STATUS = 지금 쓰고 있는 binlog 파일과 위치. 변경이 생길 때마다 위치가 커진다', '["sh", "-c", "mariadb-admin shutdown >/dev/null 2>&1; for i in $(seq 1 30); do mariadb-admin ping >/dev/null 2>&1 || break; sleep 0.5; done; printf ''[mysqld]\\\\nlog_bin=/var/lib/mysql/mysql-bin\\\\nserver_id=1\\\\n'' > /etc/mysql/mariadb.conf.d/99-binlog.cnf; nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''RESET MASTER; DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE items (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT); INSERT INTO items VALUES (1,\\"apple\\",1000),(2,\\"pear\\",2000),(3,\\"grape\\",3000),(4,\\"peach\\",4000),(5,\\"plum\\",5000);''; rm -rf /root/backup; mkdir -p /root/backup; mariadb-dump --single-transaction --master-data=2 shop > /root/backup/full.sql; mariadb shop -e \\"INSERT INTO items VALUES (6,''melon'',3500); UPDATE items SET price=1500 WHERE id=1\\"; mariadb shop -e \\"INSERT INTO items VALUES (7,''kiwi'',2500)\\"; mariadb shop -e ''DELETE FROM items''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(cat /tmp/file.txt)\\" = \\"$(mariadb -N -e \\"SHOW MASTER STATUS\\" | cut -f1)\\" ] ) && ( [ \\"$(cat /tmp/pos.txt)\\" = \\"$(mariadb -N -e \\"SHOW MASTER STATUS\\" | cut -f2)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "파일 이름이 현재 binlog 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/file.txt)\\" = \\"$(mariadb -N -e \\"SHOW MASTER STATUS\\" | cut -f1)\\" ]"]}, {"label": "위치가 현재 위치와 같다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/pos.txt)\\" = \\"$(mariadb -N -e \\"SHOW MASTER STATUS\\" | cut -f2)\\" ]"]}]', '[{"title": "MariaDB 바이너리 로그", "url": "https://mariadb.com/kb/en/binary-log/"}, {"title": "mariadb-binlog", "url": "https://mariadb.com/kb/en/mariadb-binlog/"}]'),
  (508, 3, '풀 백업이 있는데 binlog 가 또 필요한 이유', '매일 새벽에 풀 백업(dump)을 뜨는 서버에서, 오후에 누군가 실수로 테이블의 행을 모두 지웠습니다. **풀 백업만** 복원하면 어떤 한계가 있고, binlog 는 그 한계를 어떻게 메우나요?', '풀 백업은 "뜬 순간"의 모습입니다. 그 뒤에 일어난 변경은 어디에 남아 있을까요?', NULL, NULL, '[]', 'choice', '["풀 백업이 binlog 를 포함하므로 한계가 없다", "binlog 는 읽기 전용 복제본이라 복원에는 쓸 수 없다", "백업 이후의 변경은 사라진다. binlog 에는 백업 이후 변경이 순서대로 남아 있어, 실수 직전까지 다시 적용할 수 있다", "binlog 를 켜면 DELETE 가 아예 실행되지 않는다"]', 2, '풀 백업은 백업을 뜬 시점의 상태만 담습니다. 그 뒤(새벽~오후)의 정상 변경은 풀 백업에 없지만 binlog 에는 순서대로 기록돼 있습니다. 풀 백업을 복원한 뒤 binlog 를 실수 직전까지만 재생하면 그 시점으로 복구되는데, 이것이 시점 복구(PITR, Point-In-Time Recovery)입니다.', NULL, NULL, NULL, NULL),
  (508, 4, 'binlog 를 사람이 읽을 수 있게 열기', '지금 서버에는 백업 → 정상 변경 → **실수로 `DELETE FROM items`** 가 순서대로 일어났습니다. binlog 파일은 바이너리라서 `cat` 으로는 읽을 수 없고 **`mariadb-binlog 파일경로`** 로 글자로 바꿔 봅니다. 파일은 `/var/lib/mysql/mysql-bin.000001` 입니다.

1. `mariadb-binlog` 출력을 `/tmp/binlog.sql` 에 저장하세요.
2. 그 안에서 **실수로 실행된 DELETE 문장 한 줄**을 찾아 `/tmp/bad_sql.txt` 에 저장하세요.', '`mariadb-binlog 파일 > /tmp/binlog.sql` 로 저장한 뒤 `grep ''^DELETE'' /tmp/binlog.sql` 로 줄을 찾습니다. `^` 는 줄의 맨 앞을 뜻합니다.', 'mariadb-binlog /var/lib/mysql/mysql-bin.000001 > /tmp/binlog.sql
grep ''^DELETE'' /tmp/binlog.sql > /tmp/bad_sql.txt
cat /tmp/bad_sql.txt

# mariadb-binlog 는 binlog 이벤트를 SQL 문장과 ''# at 위치'' 주석으로 풀어 보여 준다', '["sh", "-c", "mariadb-admin shutdown >/dev/null 2>&1; for i in $(seq 1 30); do mariadb-admin ping >/dev/null 2>&1 || break; sleep 0.5; done; printf ''[mysqld]\\\\nlog_bin=/var/lib/mysql/mysql-bin\\\\nserver_id=1\\\\n'' > /etc/mysql/mariadb.conf.d/99-binlog.cnf; nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''RESET MASTER; DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE items (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT); INSERT INTO items VALUES (1,\\"apple\\",1000),(2,\\"pear\\",2000),(3,\\"grape\\",3000),(4,\\"peach\\",4000),(5,\\"plum\\",5000);''; rm -rf /root/backup; mkdir -p /root/backup; mariadb-dump --single-transaction --master-data=2 shop > /root/backup/full.sql; mariadb shop -e \\"INSERT INTO items VALUES (6,''melon'',3500); UPDATE items SET price=1500 WHERE id=1\\"; mariadb shop -e \\"INSERT INTO items VALUES (7,''kiwi'',2500)\\"; mariadb shop -e ''DELETE FROM items''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( grep -q \\"INSERT INTO items\\" /tmp/binlog.sql ) && ( [ \\"$(cat /tmp/bad_sql.txt)\\" = \\"DELETE FROM items\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "binlog.sql 에 이벤트가 풀려 있다", "cmd": ["sh", "-c", "grep -q \\"INSERT INTO items\\" /tmp/binlog.sql"]}, {"label": "bad_sql.txt 가 DELETE 문장이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/bad_sql.txt)\\" = \\"DELETE FROM items\\" ]"]}]', '[{"title": "MariaDB 바이너리 로그", "url": "https://mariadb.com/kb/en/binary-log/"}, {"title": "mariadb-binlog", "url": "https://mariadb.com/kb/en/mariadb-binlog/"}]'),
  (508, 5, '실수 직전 위치 찾기', '`mariadb-binlog` 출력에는 각 이벤트 앞에 `# at 숫자` 줄이 붙어 있고, 이 숫자가 **그 이벤트가 시작하는 위치**입니다. 한 문장(트랜잭션)은 `GTID` 이벤트로 시작하므로, 실수 DELETE 의 **GTID 이벤트가 시작하는 위치**가 곧 **"실수 직전"** 입니다.

실수로 실행된 `DELETE FROM items` 트랜잭션이 **시작하는 위치**를 `/tmp/bad_pos.txt` 에 숫자만 저장하세요. (파일은 `/var/lib/mysql/mysql-bin.000001`)', '출력에서 `DELETE FROM items` 가 있는 줄을 찾고, 거기서 위로 올라가며 `GTID` 가 적힌 이벤트 위의 `# at` 숫자를 보세요. `mariadb-binlog 파일 | grep -n -B8 DELETE` 처럼 앞쪽 줄도 같이 보면 편합니다.', 'mariadb-binlog /var/lib/mysql/mysql-bin.000001 | grep -n -B8 ''^DELETE''
mariadb-binlog /var/lib/mysql/mysql-bin.000001 | awk ''/GTID /{g=last} /^# at /{last=$3} /^DELETE FROM/{print g}'' > /tmp/bad_pos.txt
cat /tmp/bad_pos.txt

# 위 awk 는 ''GTID 이벤트 앞의 # at 값''을 기억해 두었다가 DELETE 를 만나면 출력한다. 이 위치를 --stop-position 에 쓰면 DELETE 는 재생되지 않는다', '["sh", "-c", "mariadb-admin shutdown >/dev/null 2>&1; for i in $(seq 1 30); do mariadb-admin ping >/dev/null 2>&1 || break; sleep 0.5; done; printf ''[mysqld]\\\\nlog_bin=/var/lib/mysql/mysql-bin\\\\nserver_id=1\\\\n'' > /etc/mysql/mariadb.conf.d/99-binlog.cnf; nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''RESET MASTER; DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE items (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT); INSERT INTO items VALUES (1,\\"apple\\",1000),(2,\\"pear\\",2000),(3,\\"grape\\",3000),(4,\\"peach\\",4000),(5,\\"plum\\",5000);''; rm -rf /root/backup; mkdir -p /root/backup; mariadb-dump --single-transaction --master-data=2 shop > /root/backup/full.sql; mariadb shop -e \\"INSERT INTO items VALUES (6,''melon'',3500); UPDATE items SET price=1500 WHERE id=1\\"; mariadb shop -e \\"INSERT INTO items VALUES (7,''kiwi'',2500)\\"; mariadb shop -e ''DELETE FROM items''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( grep -qx \\"[0-9][0-9]*\\" /tmp/bad_pos.txt ) && ( [ \\"$(cat /tmp/bad_pos.txt)\\" = \\"$(mariadb-binlog /var/lib/mysql/mysql-bin.000001 | awk ''/GTID /{g=last} /^# at /{last=$3} /^DELETE FROM/{print g}'')\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "파일에 숫자가 있다", "cmd": ["sh", "-c", "grep -qx \\"[0-9][0-9]*\\" /tmp/bad_pos.txt"]}, {"label": "DELETE 트랜잭션의 시작 위치다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/bad_pos.txt)\\" = \\"$(mariadb-binlog /var/lib/mysql/mysql-bin.000001 | awk ''/GTID /{g=last} /^# at /{last=$3} /^DELETE FROM/{print g}'')\\" ]"]}]', '[{"title": "MariaDB 바이너리 로그", "url": "https://mariadb.com/kb/en/binary-log/"}, {"title": "mariadb-binlog", "url": "https://mariadb.com/kb/en/mariadb-binlog/"}]'),
  (508, 6, 'mariadb-binlog 의 위치 옵션', '`mariadb-binlog` 로 binlog 의 **위치 1060 부터 위치 1599 앞까지**만 읽으려고 합니다. 빈칸에 알맞은 옵션을 채우세요. (시작 → 끝 순서)', '시작 위치와 끝 위치를 따로 지정하는 옵션입니다. 시각(datetime)이 아니라 숫자 위치를 쓰는 옵션을 고르세요.', NULL, NULL, '[]', 'fill', '["start-position", "stop-position", "start-datetime", "stop-datetime", "database"]', NULL, '`--start-position` 은 이 위치의 이벤트부터 읽기 시작하고, `--stop-position` 은 이 위치에 도달하면 멈춥니다(그 위치의 이벤트는 읽지 않습니다). 시각으로 지정하는 옵션은 `--start-datetime`, `--stop-datetime` 입니다.', '[0, 1]', 'mariadb-binlog --{0}=1060 --{1}=1599 mysql-bin.000001', NULL, NULL),
  (508, 7, '풀 백업이 어느 위치까지 담고 있는지 찾기', '백업 파일 `/root/backup/full.sql` 은 `mariadb-dump --single-transaction --master-data=2` 로 뜬 것입니다. 이 옵션은 백업 파일 안에 **"이 백업은 binlog 의 어느 파일, 어느 위치까지의 상태"** 인지를 주석으로 남깁니다. 이 위치부터 binlog 를 재생하면 백업 이후의 변경만 이어서 적용됩니다.

`full.sql` 에서 이 **위치 숫자**를 찾아 `/tmp/start_pos.txt` 에 숫자만 저장하세요.', '`grep -n "CHANGE MASTER" /root/backup/full.sql` 로 주석 줄을 찾습니다. `MASTER_LOG_POS=` 뒤의 숫자입니다.', 'grep ''CHANGE MASTER'' /root/backup/full.sql
grep -o ''MASTER_LOG_POS=[0-9]*'' /root/backup/full.sql | cut -d= -f2 > /tmp/start_pos.txt
cat /tmp/start_pos.txt

# --master-data=2 는 CHANGE MASTER 문장을 주석(-- )으로 남긴다. 이 위치 = 백업 직후, 재생을 시작할 곳', '["sh", "-c", "mariadb-admin shutdown >/dev/null 2>&1; for i in $(seq 1 30); do mariadb-admin ping >/dev/null 2>&1 || break; sleep 0.5; done; printf ''[mysqld]\\\\nlog_bin=/var/lib/mysql/mysql-bin\\\\nserver_id=1\\\\n'' > /etc/mysql/mariadb.conf.d/99-binlog.cnf; nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''RESET MASTER; DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE items (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT); INSERT INTO items VALUES (1,\\"apple\\",1000),(2,\\"pear\\",2000),(3,\\"grape\\",3000),(4,\\"peach\\",4000),(5,\\"plum\\",5000);''; rm -rf /root/backup; mkdir -p /root/backup; mariadb-dump --single-transaction --master-data=2 shop > /root/backup/full.sql; mariadb shop -e \\"INSERT INTO items VALUES (6,''melon'',3500); UPDATE items SET price=1500 WHERE id=1\\"; mariadb shop -e \\"INSERT INTO items VALUES (7,''kiwi'',2500)\\"; mariadb shop -e ''DELETE FROM items''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( grep -qx \\"[0-9][0-9]*\\" /tmp/start_pos.txt ) && ( [ \\"$(cat /tmp/start_pos.txt)\\" = \\"$(grep -o ''MASTER_LOG_POS=[0-9]*'' /root/backup/full.sql | cut -d= -f2)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "파일에 숫자가 있다", "cmd": ["sh", "-c", "grep -qx \\"[0-9][0-9]*\\" /tmp/start_pos.txt"]}, {"label": "백업 시점 위치와 같다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/start_pos.txt)\\" = \\"$(grep -o ''MASTER_LOG_POS=[0-9]*'' /root/backup/full.sql | cut -d= -f2)\\" ]"]}]', '[{"title": "MariaDB 바이너리 로그", "url": "https://mariadb.com/kb/en/binary-log/"}, {"title": "mariadb-binlog", "url": "https://mariadb.com/kb/en/mariadb-binlog/"}]'),
  (508, 8, '시점 복구(PITR): 위치로 재생하기', '실수로 `items` 의 모든 행이 지워졌습니다. 풀 백업(`/root/backup/full.sql`)에는 id 1~5 만 있고, 백업 이후에 **melon 추가 / apple 가격 1500 변경 / kiwi 추가** 가 있었습니다. 이 모두를 되살리세요.

1. `shop` 데이터베이스에 풀 백업을 복원합니다. (`mariadb shop < 파일`)
2. 백업 시점 위치(백업 파일의 주석)부터 **실수 DELETE 직전 위치**까지 binlog(`/var/lib/mysql/mysql-bin.000001`)를 재생합니다: `mariadb-binlog --start-position=... --stop-position=... 파일 | mariadb shop`

끝나면 `items` 가 7행이고 DELETE 는 반영되지 않아야 합니다.', '시작 위치는 백업 파일의 `CHANGE MASTER` 주석에, 끝 위치는 `mariadb-binlog` 출력에서 DELETE 의 GTID 이벤트 위 `# at` 에 있습니다. 복원을 먼저 하세요.', 'S=$(grep -o ''MASTER_LOG_POS=[0-9]*'' /root/backup/full.sql | cut -d= -f2)
B=$(mariadb-binlog /var/lib/mysql/mysql-bin.000001 | awk ''/GTID /{g=last} /^# at /{last=$3} /^DELETE FROM/{print g}'')
mariadb shop < /root/backup/full.sql
mariadb-binlog --start-position=$S --stop-position=$B /var/lib/mysql/mysql-bin.000001 | mariadb shop
mariadb shop -e ''SELECT * FROM items''

# 1) 풀 백업 복원  2) 백업 위치부터 실수 직전까지 재생. 순서가 바뀌면 안 된다', '["sh", "-c", "mariadb-admin shutdown >/dev/null 2>&1; for i in $(seq 1 30); do mariadb-admin ping >/dev/null 2>&1 || break; sleep 0.5; done; printf ''[mysqld]\\\\nlog_bin=/var/lib/mysql/mysql-bin\\\\nserver_id=1\\\\n'' > /etc/mysql/mariadb.conf.d/99-binlog.cnf; nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''RESET MASTER; DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE items (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT); INSERT INTO items VALUES (1,\\"apple\\",1000),(2,\\"pear\\",2000),(3,\\"grape\\",3000),(4,\\"peach\\",4000),(5,\\"plum\\",5000);''; rm -rf /root/backup; mkdir -p /root/backup; mariadb-dump --single-transaction --master-data=2 shop > /root/backup/full.sql; mariadb shop -e \\"INSERT INTO items VALUES (6,''melon'',3500); UPDATE items SET price=1500 WHERE id=1\\"; mariadb shop -e \\"INSERT INTO items VALUES (7,''kiwi'',2500)\\"; mariadb shop -e ''DELETE FROM items''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(mariadb -N shop -e ''SELECT COUNT(*) FROM items'')\\" = 7 ] ) && ( [ \\"$(mariadb -N shop -e \\"SELECT name FROM items WHERE id=6\\")\\" = melon ] ) && ( [ \\"$(mariadb -N shop -e \\"SELECT price FROM items WHERE id=1\\")\\" = 1500 ] ) && ( [ \\"$(mariadb -N shop -e \\"SELECT name FROM items WHERE id=7\\")\\" = kiwi ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "7행으로 돌아왔다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N shop -e ''SELECT COUNT(*) FROM items'')\\" = 7 ]"]}, {"label": "백업 이후 추가한 melon 이 있다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N shop -e \\"SELECT name FROM items WHERE id=6\\")\\" = melon ]"]}, {"label": "apple 가격 변경이 반영됐다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N shop -e \\"SELECT price FROM items WHERE id=1\\")\\" = 1500 ]"]}, {"label": "kiwi 가 있다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N shop -e \\"SELECT name FROM items WHERE id=7\\")\\" = kiwi ]"]}]', '[{"title": "MariaDB 바이너리 로그", "url": "https://mariadb.com/kb/en/binary-log/"}, {"title": "mariadb-binlog", "url": "https://mariadb.com/kb/en/mariadb-binlog/"}]'),
  (508, 9, '시점 복구: 시각으로 재생하기', '위치 대신 **시각**으로도 멈출 수 있습니다. `--stop-datetime="YYYY-MM-DD HH:MM:SS"` 는 그 시각과 **같거나 늦은** 이벤트부터는 재생하지 않습니다. 이번에는 kiwi 추가와 실수 DELETE 사이에 시간 간격이 있습니다.

1. `mariadb-binlog 파일` 출력의 이벤트 줄(`#YYMMDD HH:MM:SS server id ...`)에서 **DELETE 가 실행된 시각**을 확인합니다. (예: `#261119  8:14:59` 는 2026-11-19 08:14:59)
2. 풀 백업(`/root/backup/full.sql`)을 `shop` 에 복원한 뒤, 백업 위치부터 **DELETE 시각까지**(`--stop-datetime`) binlog(`/var/lib/mysql/mysql-bin.000001`)를 재생하세요.

끝나면 `items` 가 7행이어야 합니다.', '출력에서 DELETE 직전의 `server id` 가 있는 줄에 시각이 있습니다. `--stop-datetime` 에 그 시각(또는 1초 앞)을 `"2026-11-19 08:14:59"` 형식으로 넣으세요. 시작 위치는 이전 문제처럼 백업 파일 주석에서 구합니다.', 'S=$(grep -o ''MASTER_LOG_POS=[0-9]*'' /root/backup/full.sql | cut -d= -f2)
T=$(mariadb-binlog /var/lib/mysql/mysql-bin.000001 | awk ''/server id/{d=substr($1,2);t=$2} /^DELETE FROM/{printf "20%s-%s-%s %s", substr(d,1,2),substr(d,3,2),substr(d,5,2),t}'')
echo "$T"
mariadb shop < /root/backup/full.sql
mariadb-binlog --start-position=$S --stop-datetime="$T" /var/lib/mysql/mysql-bin.000001 | mariadb shop
mariadb shop -e ''SELECT * FROM items''

# --stop-datetime 은 그 시각 이후 이벤트를 재생하지 않는다. 같은 초에 여러 변경이 있으면 위치 방식이 더 정확하다', '["sh", "-c", "mariadb-admin shutdown >/dev/null 2>&1; for i in $(seq 1 30); do mariadb-admin ping >/dev/null 2>&1 || break; sleep 0.5; done; printf ''[mysqld]\\\\nlog_bin=/var/lib/mysql/mysql-bin\\\\nserver_id=1\\\\n'' > /etc/mysql/mariadb.conf.d/99-binlog.cnf; nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''RESET MASTER; DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE items (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT); INSERT INTO items VALUES (1,\\"apple\\",1000),(2,\\"pear\\",2000),(3,\\"grape\\",3000),(4,\\"peach\\",4000),(5,\\"plum\\",5000);''; rm -rf /root/backup; mkdir -p /root/backup; mariadb-dump --single-transaction --master-data=2 shop > /root/backup/full.sql; mariadb shop -e \\"INSERT INTO items VALUES (6,''melon'',3500); UPDATE items SET price=1500 WHERE id=1\\"; mariadb shop -e \\"INSERT INTO items VALUES (7,''kiwi'',2500)\\"; sleep 3; mariadb shop -e ''DELETE FROM items''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(mariadb -N shop -e ''SELECT COUNT(*) FROM items'')\\" = 7 ] ) && ( [ \\"$(mariadb -N shop -e \\"SELECT name FROM items WHERE id=7\\")\\" = kiwi ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "7행으로 돌아왔다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N shop -e ''SELECT COUNT(*) FROM items'')\\" = 7 ]"]}, {"label": "kiwi 가 있다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N shop -e \\"SELECT name FROM items WHERE id=7\\")\\" = kiwi ]"]}]', '[{"title": "MariaDB 바이너리 로그", "url": "https://mariadb.com/kb/en/binary-log/"}, {"title": "mariadb-binlog", "url": "https://mariadb.com/kb/en/mariadb-binlog/"}]'),
  (508, 10, '시점 복구 절차 순서', '실수로 행을 지운 것을 알았을 때, 풀 백업과 binlog 로 되살리는 **순서대로** 카드를 놓으세요.', '복원은 현재 데이터를 덮어쓰는 작업입니다. 복원하기 전에 무엇을 막고 무엇을 지켜야 할지, 결과 확인은 언제 할지 생각해 보세요.', NULL, NULL, '[]', 'order', '["복원 결과 확인 (행 수·핵심 데이터)", "binlog 를 보존하고 시작·종료 위치를 확인", "풀 백업 복원", "백업 위치부터 실수 직전까지 binlog 재생", "실수 발견: 더 이상 데이터가 바뀌지 않게 막기"]', NULL, '먼저 추가 변경을 막고, binlog 와 백업을 보존한 채 재생할 구간(시작·종료 위치)을 확인합니다. 그다음 풀 백업을 복원하고 binlog 를 재생합니다. 마지막으로 데이터를 확인합니다. binlog 를 지우거나 복원 위치를 모르는 채 시작하면 복구할 수 없습니다.', '[4, 1, 2, 3, 0]', NULL, NULL, NULL),
  (508, 11, 'binlog 파일이 둘로 나뉜 경우의 복구', '`FLUSH LOGS` 를 하거나 서버를 재시작하면 binlog 는 **새 파일로 넘어갑니다**. 이번에는 백업 뒤 변경 중 일부는 `mysql-bin.000001` 에, 나머지와 실수 DELETE 는 `mysql-bin.000002` 에 들어 있습니다. (`SHOW BINARY LOGS;` 로 확인해 보세요.)

풀 백업(`/root/backup/full.sql`)을 `shop` 에 복원한 뒤, **두 파일을 이어서** 재생하세요. `mariadb-binlog --start-position=... --stop-position=... 파일1 파일2 | mariadb shop` 에서 시작 위치는 **첫 파일**에, 끝 위치는 **마지막 파일** 안에서 적용됩니다. 끝 위치는 `mysql-bin.000002` 에서 DELETE 의 시작 위치입니다. (파일은 `/var/lib/mysql/` 에 있음)

끝나면 `items` 가 7행이어야 합니다.', '끝 위치는 `mariadb-binlog /var/lib/mysql/mysql-bin.000002` 출력에서 찾으세요. 첫 파일만 재생하면 kiwi 가 빠집니다.', 'S=$(grep -o ''MASTER_LOG_POS=[0-9]*'' /root/backup/full.sql | cut -d= -f2)
B=$(mariadb-binlog /var/lib/mysql/mysql-bin.000002 | awk ''/GTID /{g=last} /^# at /{last=$3} /^DELETE FROM/{print g}'')
mariadb shop < /root/backup/full.sql
mariadb-binlog --start-position=$S --stop-position=$B /var/lib/mysql/mysql-bin.000001 /var/lib/mysql/mysql-bin.000002 | mariadb shop
mariadb shop -e ''SELECT * FROM items''

# 복구 구간이 여러 파일에 걸치면 파일을 순서대로 모두 나열한다. 하나라도 빠지면 그 구간의 변경이 사라진다', '["sh", "-c", "mariadb-admin shutdown >/dev/null 2>&1; for i in $(seq 1 30); do mariadb-admin ping >/dev/null 2>&1 || break; sleep 0.5; done; printf ''[mysqld]\\\\nlog_bin=/var/lib/mysql/mysql-bin\\\\nserver_id=1\\\\n'' > /etc/mysql/mariadb.conf.d/99-binlog.cnf; nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''RESET MASTER; DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE items (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(30) NOT NULL, price INT); INSERT INTO items VALUES (1,\\"apple\\",1000),(2,\\"pear\\",2000),(3,\\"grape\\",3000),(4,\\"peach\\",4000),(5,\\"plum\\",5000);''; rm -rf /root/backup; mkdir -p /root/backup; mariadb-dump --single-transaction --master-data=2 shop > /root/backup/full.sql; mariadb shop -e \\"INSERT INTO items VALUES (6,''melon'',3500); UPDATE items SET price=1500 WHERE id=1\\"; mariadb -e ''FLUSH LOGS''; mariadb shop -e \\"INSERT INTO items VALUES (7,''kiwi'',2500)\\"; mariadb shop -e ''DELETE FROM items''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(mariadb -N shop -e ''SELECT COUNT(*) FROM items'')\\" = 7 ] ) && ( [ \\"$(mariadb -N shop -e \\"SELECT name FROM items WHERE id=7\\")\\" = kiwi ] ) && ( [ \\"$(mariadb -N shop -e \\"SELECT name FROM items WHERE id=6\\")\\" = melon ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "7행으로 돌아왔다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N shop -e ''SELECT COUNT(*) FROM items'')\\" = 7 ]"]}, {"label": "두 번째 파일의 kiwi 가 있다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N shop -e \\"SELECT name FROM items WHERE id=7\\")\\" = kiwi ]"]}, {"label": "첫 파일의 melon 이 있다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N shop -e \\"SELECT name FROM items WHERE id=6\\")\\" = melon ]"]}]', '[{"title": "MariaDB 바이너리 로그", "url": "https://mariadb.com/kb/en/binary-log/"}, {"title": "mariadb-binlog", "url": "https://mariadb.com/kb/en/mariadb-binlog/"}]'),
  (508, 12, '--stop-position 에 어떤 위치를 써야 할까', 'DELETE 트랜잭션은 위치 1599 에서 **시작**(GTID 이벤트)하고, 이 트랜잭션의 마지막 이벤트는 1725 에서 끝납니다. 풀 백업 복원 후 binlog 를 재생해 **DELETE 가 반영되지 않게** 하려면 `--stop-position` 에 무엇을 쓰나요?', '`--stop-position` 은 "이 위치에 도달하면 멈춘다"입니다. 멈추기 전에 DELETE 가 이미 읽혔는지 생각해 보세요.', NULL, NULL, '[]', 'choice', '["1725 (DELETE 이벤트가 끝나는 위치)", "1599 (DELETE 이벤트가 시작하는 위치)", "0 (아무 값이나 넣어도 같다)", "어느 값을 써도 다시 지워진다"]', 1, '1599 에 도달하면 멈추므로 DELETE 는 재생되지 않습니다. 1725 를 쓰면 DELETE 가 재생된 뒤에 멈추기 때문에 다시 모든 행이 지워집니다. 복구 전에는 반드시 임시 DB 등에서 재생 결과를 확인하는 습관을 들이세요.', NULL, NULL, NULL, NULL);
